#Requires -Version 5.1
<#
.SYNOPSIS
  Stage NeuralShell Windows product ZIP with installer, docs, and SHA256 hashes.

.DESCRIPTION
  Expects electron-builder output under dist/ (run npm run dist first unless -SkipBuild).
  Does not commit release-output/ artifacts.
#>
param(
  [switch]$SkipBuild,
  [string]$OutputRoot = "release-output"
)

$ErrorActionPreference = "Stop"
$RepoRoot = (Resolve-Path (Join-Path $PSScriptRoot "..")).Path
Set-Location $RepoRoot

function Get-PackageVersion {
  $pkg = Get-Content (Join-Path $RepoRoot "package.json") -Raw | ConvertFrom-Json
  return [string]$pkg.version
}

function Find-WindowsArtifacts {
  $dist = Join-Path $RepoRoot "dist"
  if (-not (Test-Path $dist)) {
    throw "dist/ not found. Run: npm ci && npm run dist"
  }

  $installer = Get-ChildItem -Path $dist -File -Filter "NeuralShell Setup *.exe" -ErrorAction SilentlyContinue |
    Sort-Object LastWriteTime -Descending |
    Select-Object -First 1

  $unpackedExe = Get-ChildItem -Path $dist -Recurse -File -Filter "NeuralShell.exe" -ErrorAction SilentlyContinue |
    Where-Object { $_.DirectoryName -match "win-unpacked" } |
    Sort-Object LastWriteTime -Descending |
    Select-Object -First 1

  if (-not $installer -and -not $unpackedExe) {
    throw "No Windows EXE found under dist/. Run: npm run dist"
  }

  return @{
    Installer = $installer
    PortableExe = $unpackedExe
  }
}

function Write-ReleaseDocs {
  param(
    [string]$StageDir,
    [string]$PrimaryExeName,
    [bool]$IsInstaller
  )

  $launchLine = if ($IsInstaller) {
    "Run the installer: $PrimaryExeName"
  } else {
    "Run: $PrimaryExeName"
  }

  @"
NeuralShell Windows Release Package

This package contains the Windows build/launcher for NeuralShell.

$launchLine

If Windows SmartScreen appears, this build may be unsigned unless a valid signature is verified.

See:
INSTALL.md
VERIFY_HASHES.txt
SHA256SUMS.txt
"@ | Set-Content -Path (Join-Path $StageDir "README_FIRST.txt") -Encoding UTF8

  @"
# NeuralShell Install Guide

## Requirements

- Windows 10/11 x64
- Standard desktop permissions

## Launch

$(if ($IsInstaller) {
  "Run the included installer ``$PrimaryExeName`` and follow the setup wizard."
} else {
  "Run the included ``$PrimaryExeName``."
})

## Security note

If this build is unsigned, Windows may show SmartScreen warnings. That does not prove malware; it means the executable has not been signed with a trusted code-signing certificate.

## Verification

Use ``SHA256SUMS.txt`` to verify files were not changed after packaging.
"@ | Set-Content -Path (Join-Path $StageDir "INSTALL.md") -Encoding UTF8

  @"
PowerShell verification:

Get-FileHash .\$PrimaryExeName -Algorithm SHA256

Compare the result with SHA256SUMS.txt.
"@ | Set-Content -Path (Join-Path $StageDir "VERIFY_HASHES.txt") -Encoding UTF8
}

function Copy-ProofDoc {
  param([string]$ProofDestDir)

  $candidates = @(
    (Join-Path $RepoRoot "docs\proofs\verify-ui-self-hosted-windows-2026-05-16.md"),
    (Join-Path $RepoRoot "docs\proof\verify-ui-self-hosted-windows-2026-05-16.md")
  )

  foreach ($src in $candidates) {
    if (Test-Path $src) {
      New-Item -ItemType Directory -Path $ProofDestDir -Force | Out-Null
      Copy-Item -Path $src -Destination (Join-Path $ProofDestDir "verify-ui-self-hosted-windows-2026-05-16.md") -Force
      return $true
    }
  }
  return $false
}

function Write-Sha256Sums {
  param(
    [string]$StageDir,
    [string]$RelativeRoot
  )

  $lines = @()
  Get-ChildItem -Path $StageDir -Recurse -File |
    Where-Object { $_.Name -ne "SHA256SUMS.txt" } |
    ForEach-Object {
      $hash = Get-FileHash $_.FullName -Algorithm SHA256
      $rel = $_.FullName.Substring($RelativeRoot.Length).TrimStart('\', '/')
      $lines += "$($hash.Hash)  $rel"
    }

  $lines | Set-Content -Path (Join-Path $StageDir "SHA256SUMS.txt") -Encoding UTF8
}

# --- main ---
$version = Get-PackageVersion
Write-Host "[package] NeuralShell v$version"

if (-not $SkipBuild) {
  Write-Host "[package] npm ci"
  npm ci
  if ($LASTEXITCODE -ne 0) { throw "npm ci failed with exit $LASTEXITCODE" }

  Write-Host "[package] npm run dist"
  npm run dist
  if ($LASTEXITCODE -ne 0) { throw "npm run dist failed with exit $LASTEXITCODE" }
}

$artifacts = Find-WindowsArtifacts
$productName = "NeuralShell-Windows-x64"
$outRoot = Join-Path $RepoRoot $OutputRoot
$stageParent = Join-Path $outRoot $productName
$appDir = Join-Path $stageParent "NeuralShell"

if (Test-Path $stageParent) {
  Remove-Item $stageParent -Recurse -Force
}
New-Item -ItemType Directory -Path $appDir -Force | Out-Null

$primary = $artifacts.Installer
$isInstaller = $true
if (-not $primary) {
  $primary = $artifacts.PortableExe
  $isInstaller = $false
}

$destName = if ($isInstaller) { $primary.Name } else { "NeuralShell.exe" }
Copy-Item -Path $primary.FullName -Destination (Join-Path $appDir $destName) -Force
Write-Host "[package] Staged primary artifact: $destName ($([math]::Round($primary.Length / 1MB, 2)) MB)"

$proofDir = Join-Path $appDir "docs\proof"
if (Copy-ProofDoc -ProofDestDir $proofDir) {
  Write-Host "[package] Included proof doc under docs/proof/"
} else {
  Write-Warning "[package] Proof doc not found; continuing without it."
}

Write-ReleaseDocs -StageDir $appDir -PrimaryExeName $destName -IsInstaller $isInstaller

$relativeRoot = (Resolve-Path $appDir).Path
Write-Sha256Sums -StageDir $appDir -RelativeRoot $relativeRoot

$zipPath = Join-Path $outRoot "$productName-product.zip"
if (Test-Path $zipPath) { Remove-Item $zipPath -Force }

Write-Host "[package] Creating ZIP: $zipPath"
Compress-Archive -Path (Join-Path $stageParent "*") -DestinationPath $zipPath -Force

$zipHash = Get-FileHash $zipPath -Algorithm SHA256
Write-Host "[package] ZIP SHA256: $($zipHash.Hash)"
Write-Host "[package] Done. Staging: $stageParent"

