const { BrowserWindow, dialog } = require("electron");

function createRecoveryWindow(report) {
  console.error("[RECOVERY] Integrity verification failed.");
  if (report) {
    console.error(`[RECOVERY] details=${JSON.stringify(report)}`);
  }

  const failedCount = Array.isArray(report && report.failedFiles)
    ? report.failedFiles.length
    : 0;
  const summary = failedCount > 0
    ? `${failedCount} file(s) failed integrity verification.`
    : String((report && report.error) || "Integrity verification failed.");

  try {
    dialog.showErrorBox("NeuralShell Recovery Mode", summary);
  } catch {
    // Fall back to console-only reporting if UI is unavailable.
  }

  const recoveryWindow = new BrowserWindow({
    width: 720,
    height: 420,
    show: true,
    center: true,
    autoHideMenuBar: true,
    webPreferences: {
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true
    }
  });

  const body = [
    "<!doctype html>",
    "<html><head><meta charset=\"utf-8\"><title>NeuralShell Recovery</title></head>",
    "<body style=\"font-family:Segoe UI,sans-serif;padding:24px;\">",
    "<h1>NeuralShell Recovery Mode</h1>",
    "<p>Integrity verification failed before the main window could open.</p>",
    `<pre style=\"white-space:pre-wrap;background:#111;color:#eee;padding:12px;border-radius:8px;\">${summary}</pre>`,
    "<p>Reinstall from a verified release package or contact support.</p>",
    "</body></html>"
  ].join("");

  recoveryWindow.loadURL(`data:text/html;charset=utf-8,${encodeURIComponent(body)}`);
}

