Write-Host "[package] cleaning stale build outputs"
function Remove-BuildTree {
  param([string]$RelativePath)
  $target = Join-Path $RepoRoot $RelativePath
  if (-not (Test-Path $target)) { return }
  try {
    Remove-Item $target -Recurse -Force -ErrorAction Stop
  } catch {
    $stale = Join-Path $RepoRoot ("{0}._stale_{1}" -f $RelativePath, (Get-Date -Format "yyyyMMddHHmmss"))
    Write-Host "[package] warn: could not remove $RelativePath ($($_.Exception.Message)); renaming to $(Split-Path $stale -Leaf)"
    Rename-Item $target $stale -Force
  }
}
foreach ($path in @("dist", "dist-renderer", $OutputRoot)) {
  Remove-BuildTree $path
}

