/** Default first-impression copy for private tester / buyer-facing shell. */
export const PRIVATE_TESTER_SHELL = true;

export function isPrivateTesterShell() {
    return PRIVATE_TESTER_SHELL;
}

const WORKFLOW_ALIASES = {
    default: 'Default Workspace',
    king: 'Primary Workspace',
    kingmode: 'Primary Workspace',
    neuralShell_quickstart: 'Quick Start',
};

export function formatWorkflowDisplayName(workflowId) {
    const raw = String(workflowId || '').trim();
    if (!raw) return 'No workspace selected';
    const alias = WORKFLOW_ALIASES[raw.toLowerCase()];
    if (alias) return alias;
    if (/king/i.test(raw)) return 'Test Workspace';
    if (raw === 'NeuralShell_QuickStart') return 'Quick Start';
    if (raw.startsWith('Workflow_')) return `Workspace ${raw.slice('Workflow_'.length)}`;
    return raw.replace(/_/g, ' ');
}

export function formatTierLabel(tierLabel, tierId) {
    if (!isPrivateTesterShell()) return String(tierLabel || tierId || 'free');
    const label = String(tierLabel || '').trim();
    const id = String(tierId || '').trim().toLowerCase();
    if (/audit/i.test(label) || id === 'auditor' || id === 'audit') return 'Review Mode';
    if (/preview/i.test(label) || id === 'free' || id === 'preview') return 'Preview';
    if (/pro/i.test(id)) return 'Pro';
    if (/enterprise/i.test(id)) return 'Enterprise';
    return label || 'Preview';
}

export function formatWatchdogStatus(status) {
    const safe = String(status || 'unknown').toLowerCase();
    if (!isPrivateTesterShell()) return safe;
    if (safe === 'running') return 'healthy';
    if (safe === 'stopped' || safe === 'degraded') return 'degraded';
    if (safe === 'fatal' || safe === 'spawn-failed') return 'needs attention';
    return 'unknown';
}

export function mapFirstBootStep(step) {
    const base = step && typeof step === 'object' ? step : {};
    if (!isPrivateTesterShell()) return base;
    const id = String(base.id || '');
    const overrides = {
        welcome_intro: {
            title: 'Welcome',
            description: 'Confirm NeuralShell is running locally on your desktop.',
        },
        provider_sweep: {
            title: 'Choose AI provider',
            description: 'Pick or confirm the model provider you want to use.',
        },
        vault_setup: {
            title: 'Set up secure storage',
            description: 'Create a local vault passphrase for saved sessions.',
        },
        policy_profile_selection: {
            title: 'Choose safety profile',
            description: 'Select how strictly outbound access is limited.',
        },
        update_ring_selection: {
            title: 'Choose update channel',
            description: 'Pick how future app updates should arrive.',
        },
        run_proof: {
            title: 'Run a quick health check',
            description: 'Optional: verify install health with a short proof run.',
        },
        license_import: {
            title: 'Add license (optional)',
            description: 'Import a license file if you received one.',
        },
        share_badge: {
            title: 'Share feedback (optional)',
            description: 'Open the feedback path or skip for now.',
        },
        open_mission_control: {
            title: 'Open the main workspace',
            description: 'Finish setup and start using the desktop workspace.',
        },
    };
    return { ...base, ...(overrides[id] || {}) };
}

export const COPY = {
    productTagline: 'Local AI workspace',
    workspacePill: 'Private desktop mode',
    gettingStartedTitle: 'Getting Started',
    gettingStartedSubtitle: 'Set up your local AI workspace.',
    welcomeTitle: 'Welcome to NeuralShell',
    welcomeBody: 'Use this workspace to run controlled local and desktop AI workflows. Start by typing a message below, opening settings, or creating a workspace.',
    welcomeSteps: [
        'Choose or confirm your AI provider',
        'Start a workspace',
        'Save or restore your session',
    ],
    composerPlaceholder: 'Ask a question or type a command…',
    auditComposerPlaceholder: 'Review mode: try /help, /status, /proof, or /workflows.',
    sessionNavTitle: 'Workspaces',
    sessionNavHeading: 'Your workspaces',
    sessionSearchPlaceholder: 'Search workspaces…',
    sessionStatusReady: 'Ready',
    sessionStatusLocked: 'Session locked — unlock to continue.',
    sessionStatusSaving: 'Saving…',
    saveSession: 'Save session',
    lockSession: 'Lock session',
    retrySave: 'Retry save',
    workbenchTitle: 'Session status',
    workbenchHeading: 'Overview',
    workbenchActiveLabel: 'Current workspace',
    workbenchVerification: 'Local verification',
    workbenchFiles: 'Workspace activity',
    ritualTitle: 'Session tools',
    ritualHint: 'Advanced session commands (optional)',
    openSettings: 'Open settings',
    startSession: 'Start session',
};

import React from 'react';
import { COPY } from '../copy/privateTesterShell.js';

export default function PrivateTesterWelcome({ onOpenSettings, onStartCommand }) {
    return (
        <motion.div className="h-full flex flex-col justify-center select-none max-w-2xl mx-auto animate-in fade-in duration-700 pb-10 space-y-6">
