                >
                    {COPY.openSettings}
                </button>
                <button
                    type="button"
                    data-testid="private-tester-start-session-btn"
                    onClick={() => {
                        if (typeof onStartCommand === 'function') onStartCommand('/help');
                    }}
                    className="px-4 py-2.5 rounded-xl border border-white/10 bg-white/5 text-sm font-medium text-slate-200 hover:bg-white/10 transition-all"
                >
                    {COPY.startSession}
                </button>
            </motion.div>
        </motion.div>
    );
}

