const http = require("http");
const { WebSocketServer } = require("ws");

const BIND_RETRY_CODES = new Set(["EACCES", "EADDRINUSE", "EADDRNOTAVAIL"]);

function safeJsonParse(raw) {
  try {
    const parsed = JSON.parse(String(raw || ""));
    return parsed && typeof parsed === "object" ? parsed : null;
  } catch {
    return null;
  }
}

function listenHttpServer(server, host, port) {
  return new Promise((resolve, reject) => {
    const onError = (err) => {
      cleanup();
      reject(err);
    };
    const cleanup = () => {
      server.removeListener("error", onError);
    };
    server.once("error", onError);
    server.listen(port, host, () => {
      cleanup();
      resolve(server);
    });
  });
}

class LocalCollabSignalServer {
  constructor(options = {}) {
    this.host = String(options.host || "127.0.0.1");
    this.requestedPort = Number(options.port || 55116);
    this.port = this.requestedPort;
    this.logger = typeof options.logger === "function" ? options.logger : () => {};
    this.wss = null;
    this.httpServer = null;
    this.rooms = new Map();
    this.enabled = true;
    this.lastError = null;
    this._startPromise = null;
  }

  status() {
    return {
      running: Boolean(this.wss && this.httpServer),
      enabled: this.enabled,
      host: this.host,
      port: this.port,
      requestedPort: this.requestedPort,
      rooms: this.rooms.size,
      lastError: this.lastError
    };
  }

  _wireWebSocketServer(wss) {
    wss.on("connection", (socket) => {
      socket.__roomId = "";
      socket.__peerId = "";

      socket.send(JSON.stringify({
        action: "ready",
        host: this.host,
        port: this.port
      }));

      socket.on("message", (raw) => {
        const message = safeJsonParse(raw);
        if (!message) return;

        const action = String(message.action || "");
        if (action === "join") {
          const roomId = String(message.room || "").trim();
          const peerId = String(message.peerId || "").trim();
          if (!roomId || !peerId) {
            socket.send(JSON.stringify({ action: "error", reason: "join_requires_room_and_peer" }));
            return;
          }
          socket.__roomId = roomId;
          socket.__peerId = peerId;
          if (!this.rooms.has(roomId)) {
            this.rooms.set(roomId, new Set());
          }
          this.rooms.get(roomId).add(socket);
          socket.send(JSON.stringify({
            action: "joined",
            room: roomId,
            peerId
          }));
          return;
        }

        if (action === "publish") {
          const roomId = String(message.room || socket.__roomId || "").trim();
          if (!roomId || !this.rooms.has(roomId)) return;
          const peers = this.rooms.get(roomId);
          const packet = JSON.stringify({
            action: "event",
            room: roomId,
            fromPeerId: String(socket.__peerId || ""),
            eventType: String(message.eventType || ""),
            payload: message.payload && typeof message.payload === "object" ? message.payload : {},
            sentAt: new Date().toISOString()
          });
          for (const peerSocket of peers) {
            if (peerSocket === socket) continue;
            if (peerSocket.readyState !== peerSocket.OPEN) continue;
            peerSocket.send(packet);
          }
        }
      });

      socket.on("close", () => {
        const roomId = String(socket.__roomId || "");
        if (!roomId || !this.rooms.has(roomId)) return;
        const peers = this.rooms.get(roomId);
        peers.delete(socket);
        if (peers.size === 0) {
          this.rooms.delete(roomId);
        }
      });
    });
  }

  _cleanupPartial() {
    if (this.wss) {
      try {
        this.wss.close();
      } catch {
        // ignore
      }
      this.wss = null;
    }
    if (this.httpServer) {
      try {
        this.httpServer.close();
      } catch {
        // ignore
      }
      this.httpServer = null;
    }
    this.rooms.clear();
  }

  async _bindOnce(port) {
    const httpServer = http.createServer();
    await listenHttpServer(httpServer, this.host, port);
    const address = httpServer.address();
    const boundPort = address && typeof address === "object" ? Number(address.port) : Number(port);
    const wss = new WebSocketServer({ server: httpServer });
    this._wireWebSocketServer(wss);
    this.httpServer = httpServer;
    this.wss = wss;
    this.port = boundPort;
    return boundPort;
  }

  async _startInternal() {
    if (this.wss && this.httpServer) {
      return this.status();
    }

    const preferred = Number.isFinite(this.requestedPort) && this.requestedPort >= 0
      ? this.requestedPort
      : 55116;
    const bindPorts = preferred === 0 ? [0] : [preferred, 0];

    for (const candidatePort of bindPorts) {
      try {
        const boundPort = await this._bindOnce(candidatePort);
        this.enabled = true;
        this.lastError = null;
        this.logger("started", {
          host: this.host,
          port: boundPort,
          requestedPort: preferred
        });
        return this.status();
      } catch (err) {
        this._cleanupPartial();
        const code = err && err.code ? String(err.code) : "";
        const retriable = BIND_RETRY_CODES.has(code);
        if (candidatePort === 0 || !retriable) {
          this.enabled = false;
          this.lastError = err && err.message ? err.message : String(err);
          this.logger("disabled", {
            host: this.host,
            requestedPort: preferred,
            code: code || "unknown",
            message: this.lastError
          });
          return this.status();
        }
      }
    }

    this.enabled = false;
    return this.status();
  }

  start() {
    if (this.wss && this.httpServer) {
      return Promise.resolve(this.status());
    }
    if (this._startPromise) {
      return this._startPromise;
    }
    this._startPromise = this._startInternal().finally(() => {
      this._startPromise = null;
    });
    return this._startPromise;
  }

  stop() {
    if (!this.wss && !this.httpServer) return;
    for (const peers of this.rooms.values()) {
      for (const socket of peers) {
        try {
          socket.close(1001, "server_shutdown");
        } catch {
          // ignore
        }
      }
    }
    this.rooms.clear();
    if (this.wss) {
      try {
        this.wss.close();
      } catch {
        // ignore
      }
      this.wss = null;
    }
    if (this.httpServer) {
      try {
        this.httpServer.close();
      } catch {
        // ignore
      }
      this.httpServer = null;
    }
    this.logger("stopped", {
      host: this.host,
      port: this.port
    });
  }
}

module.exports = {
  LocalCollabSignalServer
};

