function Add-Artifact($item, $kind, $rootLabel) {
  if (-not $item) { return }
  try {
    $resolved = (Resolve-Path $item.FullName -ErrorAction Stop).Path
  } catch { $resolved = $item.FullName }
  $script:results.Add([PSCustomObject]@{
    Kind=$kind; Root=$rootLabel; Path=$resolved; Name=$item.Name
    Size=$item.Length; Modified=$item.LastWriteTime
  })
}

