function Fingerprint-File($path) {
  if (-not (Test-Path $path)) { return $null }
  $item = Get-Item $path
  $kind = switch -Regex ($item.Name) {
    'Setup.*\.exe$' { 'installer' }
    'app\.asar$' { 'app.asar' }
    'index-.*\.js$' { 'bundle-js' }
    'index-.*\.css$' { 'bundle-css' }
    'AdaptiveLayoutEngine\.jsx$' { 'source-ALE' }
    default { 'file' }
  }
  $sha = (Get-FileHash $path -Algorithm SHA256).Hash
  $text = $null
  $fps = @()
  if ($kind -in @('bundle-js','installer','app.asar') -and $item.Length -lt 50MB) {
    try {
      if ($kind -eq 'bundle-js') {
        $t = [IO.File]::ReadAllText($path)
        $fps = $markers | Where-Object { $t.Contains($_) }
      }
    } catch {}
  }
  [PSCustomObject]@{
    Kind=$kind; Path=(Resolve-Path $path).Path; Name=$item.Name
    Modified=$item.LastWriteTime; SizeMB=[math]::Round($item.Length/1MB,3)
    SHA256=$sha; AfterMay2=($item.LastWriteTime -gt $may2)
    Fingerprints=($fps -join '; ')
  }
}

